@* Manages wizard step navigation and holds the shared Order state. *@

<div class="checkout-wizard">
    <h2>Checkout</h2>

    <div class="step-indicator">
        <span class="@StepClass(1)">1. Shipping</span>
        <span class="@StepClass(2)">2. Payment</span>
    </div>

    @if (_currentStep == 1)
    {
        <ShippingStep Shipping="_order.Shipping" OnNext="GoToPayment" />
    }
    else
    {
        <PaymentStep Payment="_order.Payment"
                     OnBack="GoToShipping"
                     OnPlaceOrder="PlaceOrder" />
    }
</div>

@code {
    /// <summary>
    /// Fired when the user confirms the order from the final step.
    /// </summary>
    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private int _currentStep = 1;

    private void GoToPayment() => _currentStep = 2;
    private void GoToShipping() => _currentStep = 1;

    private async Task PlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }

    private string StepClass(int step) =>
        step == _currentStep ? "step active" : "step";
}

@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_isValidating">
    <legend>Shipping Information</legend>

    <div class="form-group">
        <label for="name">Name</label>
        <input id="name" @bind="Shipping.Name" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address</label>
        <input id="address" @bind="Shipping.Address" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="city">City</label>
        <input id="city" @bind="Shipping.City" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="zip">Zip Code</label>
        <input id="zip" @bind="Shipping.ZipCode" @bind:event="oninput" />
    </div>
</fieldset>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="validation-error" role="alert">@_errorMessage</div>
}

<div class="step-actions">
    <button class="btn-next" @onclick="ValidateAndProceed" disabled="@_isValidating">
        @if (_isValidating)
        {
            <span class="spinner" aria-hidden="true"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _errorMessage;

    // Linked to a root source so Dispose can cancel everything at once.
    private CancellationTokenSource _disposeCts = new();
    // Per-validation source; replaced on each new attempt to cancel stale requests.
    private CancellationTokenSource? _validationCts;

    private async Task ValidateAndProceed()
    {
        _errorMessage = null;

        // Cancel any in-flight validation from a previous click.
        _validationCts?.Cancel();
        _validationCts?.Dispose();
        _validationCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        var token = _validationCts.Token;
        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be verified. Please check your details.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — either a newer request replaced this one
            // or the component was disposed. Nothing to do.
        }
        catch (Exception)
        {
            _errorMessage = "An error occurred while validating the address. Please try again.";
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void Dispose()
    {
        // Signal cancellation to any in-flight validation, then clean up.
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _validationCts?.Cancel();
        _validationCts?.Dispose();
    }
}

